-- Agronomist schema. Run with Supabase CLI/database migration tooling.
create extension if not exists pgcrypto;
create type public.user_role as enum ('FARMER', 'CUSTOMER', 'ADMIN');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', email text, phone_number text, date_of_birth date, profile_image text, role public.user_role not null default 'CUSTOMER', preferred_language text not null default 'en' check (preferred_language in ('en','ta','hi','te','kn','ml')), village text, district text, state text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.farmer_profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.profiles(id) on delete cascade, farming_type text, farming_schedule text, available_workers integer not null default 0 check (available_workers >= 0), owns_selling_market boolean not null default false, irrigation_facility text, address text, village text, district text, state text, latitude double precision, longitude double precision, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.land_plots (id uuid primary key default gen_random_uuid(), farmer_id uuid not null references public.profiles(id) on delete cascade, plot_name text not null, total_area_acres numeric(12,4) not null check (total_area_acres > 0), display_area numeric(12,4) not null, area_unit text not null check (area_unit in ('acre','cent','hectare')), latitude double precision, longitude double precision, soil_type text not null default 'Unknown', soil_ph numeric(4,2), nitrogen numeric, phosphorus numeric, potassium numeric, organic_carbon numeric, soil_moisture numeric, water_holding_capacity text, irrigation_type text not null default 'none', soil_data_source text, soil_data_verified boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.crop_allocations (id uuid primary key default gen_random_uuid(), plot_id uuid not null references public.land_plots(id) on delete cascade, crop_name text not null, allocated_area_acres numeric(12,4) not null check (allocated_area_acres > 0), area_unit text not null, planting_date date, expected_harvest_date date, actual_harvest_date date, crop_status text not null default 'planned', estimated_yield numeric, created_at timestamptz not null default now());
create table public.soil_test_records (id uuid primary key default gen_random_uuid(), plot_id uuid not null references public.land_plots(id) on delete cascade, test_date date not null, ph numeric(4,2), nitrogen numeric, phosphorus numeric, potassium numeric, organic_carbon numeric, electrical_conductivity numeric, micronutrients jsonb, laboratory_name text, source text not null, verification_status text not null default 'unverified', created_at timestamptz not null default now());
create table public.marketplace_products (id uuid primary key default gen_random_uuid(), farmer_id uuid not null references public.profiles(id) on delete cascade, product_name text not null, category text not null, description text, quantity_available numeric not null check (quantity_available >= 0), quantity_unit text not null check (quantity_unit in ('kg','quintal','litre')), price_per_unit numeric not null check (price_per_unit > 0), harvest_date date, contact_number text not null, selling_latitude double precision, selling_longitude double precision, selling_address text, pickup_available boolean not null default true, delivery_available boolean not null default false, status text not null default 'active' check (status in ('active','sold','draft')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_images (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.marketplace_products(id) on delete cascade, image_url text not null, storage_path text not null unique, created_at timestamptz not null default now());
create table public.marketplace_enquiries (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.marketplace_products(id) on delete cascade, customer_id uuid not null references public.profiles(id) on delete cascade, farmer_id uuid not null references public.profiles(id) on delete cascade, enquiry_message text not null, status text not null default 'new', created_at timestamptz not null default now());
create table public.farming_expenses (id uuid primary key default gen_random_uuid(), farmer_id uuid not null references public.profiles(id) on delete cascade, plot_id uuid references public.land_plots(id) on delete set null, crop_allocation_id uuid references public.crop_allocations(id) on delete set null, expense_category text not null, amount numeric not null check (amount >= 0), description text, expense_date date not null, created_at timestamptz not null default now());
create index land_plots_farmer_idx on public.land_plots(farmer_id); create index allocations_plot_idx on public.crop_allocations(plot_id); create index products_search_idx on public.marketplace_products(status, category, price_per_unit); create index enquiries_farmer_idx on public.marketplace_enquiries(farmer_id, created_at desc);

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id, full_name, email, role, preferred_language) values (new.id, coalesce(new.raw_user_meta_data->>'full_name',''), new.email, case when new.raw_user_meta_data->>'role' = 'FARMER' then 'FARMER'::public.user_role else 'CUSTOMER'::public.user_role end, coalesce(new.raw_user_meta_data->>'preferred_language','en')); if new.raw_user_meta_data->>'role' = 'FARMER' then insert into public.farmer_profiles(user_id) values (new.id); end if; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

alter table public.profiles enable row level security; alter table public.farmer_profiles enable row level security; alter table public.land_plots enable row level security; alter table public.crop_allocations enable row level security; alter table public.soil_test_records enable row level security; alter table public.marketplace_products enable row level security; alter table public.product_images enable row level security; alter table public.marketplace_enquiries enable row level security; alter table public.farming_expenses enable row level security;
create policy "profile self read" on public.profiles for select using (auth.uid() = id); create policy "profile self update" on public.profiles for update using (auth.uid() = id) with check (auth.uid() = id and role = (select role from public.profiles where id = auth.uid()));
create policy "farmer owns plots" on public.land_plots for all using (farmer_id = auth.uid()) with check (farmer_id = auth.uid()); create policy "farmer owns allocations" on public.crop_allocations for all using (exists(select 1 from public.land_plots p where p.id = plot_id and p.farmer_id = auth.uid())) with check (exists(select 1 from public.land_plots p where p.id = plot_id and p.farmer_id = auth.uid())); create policy "farmer owns soil tests" on public.soil_test_records for all using (exists(select 1 from public.land_plots p where p.id = plot_id and p.farmer_id = auth.uid())) with check (exists(select 1 from public.land_plots p where p.id = plot_id and p.farmer_id = auth.uid()));
create policy "public active products" on public.marketplace_products for select using (status = 'active' or farmer_id = auth.uid()); create policy "farmer owns products" on public.marketplace_products for all using (farmer_id = auth.uid()) with check (farmer_id = auth.uid()); create policy "product images visible" on public.product_images for select using (true); create policy "enquiries customer create" on public.marketplace_enquiries for insert with check (customer_id = auth.uid()); create policy "enquiries participants read" on public.marketplace_enquiries for select using (customer_id = auth.uid() or farmer_id = auth.uid());
